#[derive(Debug, Clone)]
pub(crate) enum ManagedLocalTaskOutcome {
    RuntimeInstalled(ManagedRuntimeInstallation),
    WslProvisioned,
    RestartContinuationVerified,
    EnvironmentRemoved(ManagedExecutionEnvironment),
    ModelRegistered(ManagedModelRegistration),
    ModelPrepared {
        model_id: String,
        environment: ManagedExecutionEnvironment,
    },
}

pub(crate) struct ManagedLocalTask {
    result: Receiver<Result<ManagedLocalTaskOutcome, ManagedLocalRuntimeError>>,
}

impl ManagedLocalTask {
    pub(crate) fn install_runtime(
        manager: ManagedLocalRuntime,
        environment: ManagedExecutionEnvironment,
    ) -> Result<Self, ManagedLocalRuntimeError> {
        Self::spawn("ai-managed-runtime-install", move || {
            manager
                .install_pinned_runtime(environment)
                .map(ManagedLocalTaskOutcome::RuntimeInstalled)
        })
    }

    pub(crate) fn provision_wsl(
        manager: ManagedLocalRuntime,
    ) -> Result<Self, ManagedLocalRuntimeError> {
        Self::spawn("ai-managed-wsl-provision", move || {
            manager.provision_managed_wsl_distribution()?;
            Ok(ManagedLocalTaskOutcome::WslProvisioned)
        })
    }

    pub(crate) fn resume_after_restart(
        manager: ManagedLocalRuntime,
    ) -> Result<Self, ManagedLocalRuntimeError> {
        Self::spawn("ai-managed-restart-check", move || {
            manager.resume_after_restart()?;
            Ok(ManagedLocalTaskOutcome::RestartContinuationVerified)
        })
    }

    pub(crate) fn remove_environment(
        manager: ManagedLocalRuntime,
        environment: ManagedExecutionEnvironment,
    ) -> Result<Self, ManagedLocalRuntimeError> {
        Self::spawn("ai-managed-environment-remove", move || {
            manager.remove_environment(environment)?;
            Ok(ManagedLocalTaskOutcome::EnvironmentRemoved(environment))
        })
    }

    pub(crate) fn register_existing_gguf(
        manager: ManagedLocalRuntime,
        path: PathBuf,
    ) -> Result<Self, ManagedLocalRuntimeError> {
        Self::spawn("ai-managed-model-register", move || {
            manager
                .register_existing_gguf(&path, None)
                .map(ManagedLocalTaskOutcome::ModelRegistered)
        })
    }

    pub(crate) fn prepare_model(
        manager: ManagedLocalRuntime,
        model_id: String,
        environment: ManagedExecutionEnvironment,
    ) -> Result<Self, ManagedLocalRuntimeError> {
        Self::spawn("ai-managed-model-prepare", move || {
            manager.prepare_model_for_environment(&model_id, environment, true)?;
            Ok(ManagedLocalTaskOutcome::ModelPrepared { model_id, environment })
        })
    }

    fn spawn(
        name: &str,
        operation: impl FnOnce() -> Result<ManagedLocalTaskOutcome, ManagedLocalRuntimeError>
            + Send
            + 'static,
    ) -> Result<Self, ManagedLocalRuntimeError> {
        let (sender, result) = mpsc::channel();
        thread::Builder::new()
            .name(name.to_owned())
            .spawn(move || {
                let _ = sender.send(operation());
            })
            .map_err(|error| {
                ManagedLocalRuntimeError::new(
                    ManagedDiagnosticLayer::OperatingSystemPrerequisite,
                    format!("could not start managed Local AI setup worker: {error}"),
                )
            })?;
        Ok(Self { result })
    }

    pub(crate) fn poll(
        &self,
    ) -> Option<Result<ManagedLocalTaskOutcome, ManagedLocalRuntimeError>> {
        match self.result.try_recv() {
            Ok(result) => Some(result),
            Err(TryRecvError::Empty) => None,
            Err(TryRecvError::Disconnected) => Some(Err(ManagedLocalRuntimeError::new(
                ManagedDiagnosticLayer::OperatingSystemPrerequisite,
                "managed Local AI setup worker disconnected unexpectedly",
            ))),
        }
    }
}
